   [6]={next_id=7, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="走廊里偶尔有穿着制服的女职员匆匆走过，靴跟敲击水磨石地面，发出清脆而短促的回响。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [7]={next_id=8, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="此时，相距不远的链尉官办公室内。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [8]={next_id=9, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你脸朝下趴着，手臂交叠垫在下巴底下。沙发垫被你压出一个浅浅的人形凹陷，皮革的味道混着药膏的清凉气息，在鼻尖缠绕。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
