   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是在给我们的链尉官进行“深度物理理疗”？还是在测试总部新采购的沙发承重质量？", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老师，你听我解释……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="闪蝶，莱斯坦斯《内务条例》第七章，第四十九条，关于办公区域行为规范，里面是怎么写的？", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [35]={next_id=36, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……不……不得进行与公务无关的……私人……私人亲密活动……", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对，对不起……伊西丝分局长……我、我只是想……", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伊西丝看着她快哭出来的样子，语气放缓了些。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="想让他开心？我知道。但这里是办公区域，任何时候，都要记得分清楚场合。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……是，我记住了。伊西丝分局长，对不起。", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伊西丝无奈的摸了摸闪蝶的头，眼中泛起一丝温柔，随后看向你。正当你以为她要对你进行说教时，伊西丝从口袋里掏出一封米白色的信封，将它递给你。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="纸质考究，封口处印着一个简简单单的唇印。色泽浓郁，形状饱满，显然不是随意印上去的。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="给，歌海娜给你寄了封信。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="歌海娜？写信？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4522", 0, 0, 2.5, 223},{ 3, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="展开信纸，字迹修长而潇洒，墨水里似乎掺了某种香料，散发着一缕若有若无的香气。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="亲爱的链尉官，\n当你看到这封信的时候，我正在福登城的月夜之吻酒吧里喝着今年的第一批蜂蜜酒。味道不错，可惜你不在。\n好了，废话不多说。拉蒂夫家族的小小姐最近找上我，说市面上出现了一大批假源晶。", msg_color="", msg_size=0, talker="信", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="外表和真的源晶一模一样，但根本不能用来做任何正经事。\n这事已经影响到整个尤赞坦的市场秩序了，星钻拜托我帮忙处理这件事情。\n我顺着线索追下去，发现假源晶的源头指向一个叫弗亚矿区的地方。", msg_color="", msg_size=0, talker="信", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那地方，怎么说呢——乱得像捅了的马蜂窝。\n明面上有个叫“凯瑞”的公司把持着，暗地里各方势力犬牙交错。\n原本以我的能力，可以处理好这件事。但最近……弗亚矿区似乎变得有些不一样了。", msg_color="", msg_size=0, talker="信", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我在那边的一些“手段”告诉我，遇到了些麻烦，进展一直不是很顺利。\n思来想去，能够帮我处理这件事情的人，只有你了。", msg_color="", msg_size=0, talker="信", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="另外……我给你准备了个小玩意儿，一并放在信封里了。\n如果你愿意帮忙的话，就带着那个“小玩意儿”来月夜之吻找我。", msg_color="", msg_size=0, talker="信", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [50]={next_id=51, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="读完信，从信封里倒出那枚“假源晶”和一枚银色的小挂坠。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_206.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
