   [116]={next_id=117, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这便是接下来我要说的事情。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="歌海娜神秘一笑，但熟知歌海娜性格的你知道她似乎隐瞒了什么事情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你要去的弗亚矿区，在赞布拉城往外数百公里处，有着一个叫“大空洞”的地下聚居地。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="说是聚居地，其实就是个被挖空了的废弃矿洞。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="矿洞？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [121]={next_id=122, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对。当年那地方源晶储量丰富，吸引了无数矿工、商人、佣兵蜂拥而去。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="人越来越多，矿洞越挖越大。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来资源枯竭了，那里也逐渐没落。但有些人已经在那里扎了根，所以留了下来，形成了现在的大空洞。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不过最近又传出消息说发现了新矿藏，那地方又热闹起来了。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那凯瑞公司是怎么回事？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在尤赞坦，不管是什么利益，拉蒂夫家族总是吃大头的那一个。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而那些小公司只能捡他们的剩饭，“凯瑞公司”算是剩饭里吃得最饱的那个。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [128]={next_id=129, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弗亚矿区名义上是凯瑞公司的地盘，但实际上……", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [129]={next_id=130, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="实际上？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [130]={next_id=131, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="鱼龙混杂。佣兵、黑帮、走私犯、逃犯……那里不受官方管辖，是个三不管地带。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [131]={next_id=132, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="拉蒂夫家族也曾尝试彻底掌控那个地方，但最后总是因为莫名的原因而失败。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [132]={next_id=133, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那里常年被特殊的磁场干扰，寻常的通讯手段在那里根本不起作用，所以我也对那里束手无策。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
