   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="要记住，无论遇到什么困难，要以保证自身安全为第一。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
